output_db = {}

# Expand into rich sentences
for code, details in countries_info.items():
    name, cap, cont, pop, cur, lang, map_desc, flag_desc, free_desc, chal_desc = details
    
    # Map Formation
    map_p = f"Positioned in the region of {cont}, the geography of {name} is characterized by its {map_desc}. The historical boundaries of the nation were formed through complex territorial treaties, regional migration, and physical borders that slowly shaped the sovereign map we recognize today."
    
    # Flag Creation
    flag_p = f"The national flag of {name} features a prominent design with a {flag_desc}. This flag stands as a powerful emblem of national identity, combining historical colors and symbolic elements that reflect the cultural heritage and core values of the country."
    
    # Freedom Story
    free_p = f"The path to independence for {name} concluded when the nation achieved full sovereignty from {free_desc}. This historic transition was the culmination of national movements, courageous struggles, and diplomatic agreements that established a free country."
    
    # Challenges
    chal_p = f"{name} faces several contemporary challenges, particularly dealing with {chal_desc}. The government and citizens continue to navigate these social, economic, and environmental difficulties as they strive toward sustainable development and stability."
    
    output_db[code.lower()] = {
        "name": name,
        "code": code,
        "capital": cap,
        "continent": cont,
        "population": pop,
        "currency": cur,
        "languages": lang,
        "mapFormation": map_p,
        "flagHistory": flag_p,
        "freedomStory": free_p,
        "challenges": chal_p
    }

print(f"Total countries generated: {len(output_db)}")

# Save to countriesData.js
target_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "../src/lib/countriesData.js"))
os.makedirs(os.path.dirname(target_path), exist_ok=True)

with open(target_path, "w", encoding="utf-8") as f:
    f.write("// Detailed database of 196 sovereign nations of the world\n")
    f.write("// Generated by generate_countries.py\n\n")
    f.write("export const countriesData = ")
    json.dump(output_db, f, indent=2, ensure_ascii=False)
    f.write(";\n")

print(f"Successfully generated database at: {target_path}")
